def _entry(problem_id, n):
    return EXPLANATIONS.get(problem_id, {}).get(n)


def explanation_for(problem_id, n):
    entry = _entry(problem_id, n)
    if not entry:
        return ""
    if isinstance(entry, (tuple, list)):
        return entry[-1]
    return entry


def topic_for(problem_id, n):
    entry = _entry(problem_id, n)
    if isinstance(entry, (tuple, list)) and len(entry) > 1:
        return entry[0]
    return ""
